mapper.update:
UPDATE exam
SET title = #{title}, courseid = #{courseid}, description = #{description}, content = #{content},
    duration = #{duration}, total_score = #{totalScore}, starttime = #{starttime},
    endtime = #{endtime}, status = #{status}, anti_cheat = #{antiCheat}
WHERE examid = #{examid}

mapper.select:
SELECT e.*, c.coursename, (SELECT COUNT(*) FROM exam_record er WHERE er.examid = e.examid AND er.status >= 1) AS submitted_count FROM exam e LEFT JOIN course c ON e.courseid = c.courseid WHERE e.teacherid = #{teacherid}
AND (e.title LIKE CONCAT('%', #{keyword}, '%') OR c.coursename LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.examid DESC LIMIT #{offset}, #{limit}

SELECT s.studentid, s.studentno, s.studentname, ci.classname
FROM student s
JOIN courseclass cc ON s.classid = cc.classid
JOIN exam e ON cc.courseid = e.courseid
JOIN classinfo ci ON s.classid = ci.classid
WHERE e.examid = #{examid}
  AND s.studentid NOT IN (
      SELECT er.studentid FROM exam_record er WHERE er.examid = #{examid}
  )
ORDER BY ci.classname, s.studentno
